NAME_LIMIT = 64
"""The longest name greeting() accepts, in Unicode code points."""


def greeting(name: str | None = None) -> str:
    """The greeting `hello, <name>`; with no name, `hello, demo`.

    A name longer than NAME_LIMIT code points raises ValueError.
    """
    if name is None:
        name = "demo"
    if len(name) > NAME_LIMIT:
        raise ValueError(
            f"name is {len(name)} code points; the limit is {NAME_LIMIT}"
        )
    return f"hello, {name}"
